from pathlib import Path

ROOT = Path(__file__).resolve().parents[4]


def edit(name, changes, additions=None):
    p = ROOT / 'results/T-032' / name
    raw = p.read_bytes()
    nl = '\r\n' if b'\r\n' in raw else '\n'
    lines = raw.decode('utf-8').splitlines()
    for number, (anchor, new) in changes.items():
        assert anchor in lines[number - 1], (name, number, lines[number - 1])
        lines[number - 1] = new
    for number, text in sorted((additions or {}).items(), reverse=True):
        lines[number:number] = ['', text]
    p.write_bytes((nl.join(lines) + nl).encode('utf-8'))


edit('nguyen-nhan-xep-hang.md', {
    3: ('Người làm: Claude.', 'Người làm lịch sử: Claude. Bản tổng hợp phiên12–13 ngày 11/10/2026; Codex sửa sau REVIEW theo lời Minh duyệt cùng ngày. Trạng thái: chờ phiên Codex mới kiểm lại. Bản trước phiên12–13 ở các thư mục tong-hop-phien-12-001/ban-truoc/ và tong-hop-phien-13-001/ban-truoc/; bản trước lượt sửa này ở runs/sua-review-001/ban-truoc/. Không đổi kết quả đóng băng.'),
    13: ('Giả thuyết', '3. **Dịch vụ gọi bị chấm cao vì phải chờ root có bằng chứng ở một phần ca, tùy phương pháp.** Với TraceRCA, chuỗi tính toán được xác nhận ở 4/4 và 9/15 cặp xét được. Với MicroRank, tiêu chí liên kết hiện tại không hỗ trợ cách giải thích này ở đa số cặp (0/10 và 4/16); phép đổi thời lượng chưa đủ bác bỏ đường cờ → nhóm trace → điểm. Với BARO ở RE2-TT, chỉ 5/103 cặp vừa trên chuỗi gọi vừa có cột đổi tại mốc. Chờ cũng có ở ca đúng, nên riêng hiện tượng này không phân biệt ca sai.'),
    15: ('Có những ca', '5. **Có những ca chưa định vị được root bằng cách chấm hiện tại.** Ở 3/4 ca return của Nezha-OB, root không đứng hạng1 dưới các cách chấm trong bảng kiểm; điều này chưa chứng minh dữ liệu không có dấu hiệu do lỗi. Ở 8/52 ca không có cạnh gọi đi vào root, nên cách dựa riêng vào cạnh đi vào không áp dụng. Một số dịch vụ không liên hệ có metric đổi tại mốc mà dữ liệu chưa cho biết vì sao.'),
    62: ('Giả thuyết bị bác', 'Phép đổi cờ sang phần span chưa được span con phủ giữ nguyên 248/252 cặp và 19/20 cặp dịch vụ gọi (KQ10 mục2). Kết quả cho thấy đổi riêng đại lượng thời lượng chưa gỡ được đa số cặp; chưa đủ kết luận dịch vụ gọi không bị ảnh hưởng bởi chờ. Mã MicroRank chia một trace vào nhóm bất thường khi bất kỳ span nào mang cờ, rồi dùng mọi span của trace đó để dựng đồ thị và đếm phủ. Nếu cờ của dịch vụ gọi mất nhưng cờ của root hoặc dịch vụ khác còn, trace vẫn ở nhóm cũ; riêng thay đổi cờ ấy không đổi đồ thị/đếm phủ. Phần cần kiểm là cờ nào giữ trace trong nhóm và nhóm nào đổi; xem bổ sung sau REVIEW ở mục7.'),
    76: ('| H7 |', '| H7 | Trễ mạng → bất thường có thể hiện ở span phía gọi rõ hơn span của root → cách tính theo dịch vụ sở hữu span có thể chấm dịch vụ gọi cao hơn root | Nezha-OB, 6 ca: root đứng đầu theo span của mình ở 1/6, theo span phía gọi ở 5/6; BARO, SimpleRCA, TraceRCA xếp root hạng1 ở 0, 1, 0 trên6. KQ10 mục3; KQ11 mục7 | Quan sát; không suy ra span của root luôn không có tín hiệu hoặc mọi phép chấm theo nút đều thất bại | Nêu một phần | M + D |'),
    77: ('| H8 |', '| H8 | Return ở Nezha-OB → các cách chấm hiện tại chưa tách được root ở phần lớn ca; đáp ứng do lỗi còn chưa phân xử | 3/4 ca root không hạng1 dưới các cách chấm trong bảng root-signal-by-fault, KQ11 mục7. Root vẫn có span mang cờ ở các ca này; đó cũng chưa chứng minh cờ do lỗi | Quan sát về thứ hạng; không phải xác nhận thiếu tín hiệu trong dữ liệu | Bài MicroRank nêu giới hạn khi lỗi không đổi độ trễ; chưa xác nhận điều kiện ấy cho từng ca này | OPEN giữa dữ liệu và cách tính |'),
    96: ('| H15 |', '| H15 | Hồi quy trên111 điểm, chấm10 điểm cuối → phần dư train nhỏ mà phần dư chấm không nhỏ theo → điểm có cạnh cao hơn điểm không cạnh | 3.285/4.526 nút; tỷ số tăng theo số cha (KQ10 mục1.4). Đổi cửa sổ: trung vị nhóm từ8 cha 7,54 → 3,40 (học291 điểm), 3,64 (chấm ngay sau mốc); tỷ lệ nút tăng72,6% →67,3%,73,1% (KQ13 mục6) | Xác nhận phép tính; quan sát độ nhạy cửa sổ. Chưa tách riêng số điểm học, phân phối, vị trí chấm và tập nút | Có nêu dạng tổng quát | M + G |'),
    142: ('H2, H3', '- **H2, H3 (MicroRank, đếm phủ và trọng số).** Sau khi thay bộ chia, còn25–26/47 ca root chưa hạng1. Ghép thêm đếm riêng (KQ12 mục1) tăng số hạng1 từ21–22 lên23–27/47; RE2-TT đạt17–19/25, Nezha-OB6–8/22. Còn20–24 ca. Bảng nối (KQ13 mục5) cho frontend gắn với root ở3/14 và3/11 ca frontend đứng đầu, nên không thể gán toàn bộ cho H4,H7. Ba dạng quan sát được là: thao tác đứng đầu bao lời gọi chậm tới root; các trace tạo số đếm cho thao tác đứng đầu không có root; hoặc dưới5 span tạo điểm. Đây chưa phải phân loại đầy đủ nguyên nhân: dev-14701a3bbb chưa rõ dưới cả hai luật; dưới luật code, dev-607751ac0a bị xếp không gắn nhưng vẫn có root trong2/6 trace xét. Không gọi toàn bộ nhóm trace bất thường là không chứa root. Trên52 đơn vị native có46 OK sai,2 OK đúng,4 ERROR; phần đọc tay có48 đơn vị gồm46 OK sai,1 ERROR và1 đối chứng đúng (bao-phu-nhom.json → /units, method=microrank_full). Ba phản ví dụ của bộ chia mới được giữ; cơ chế các ca chưa rõ còn OPEN.'),
    145: ('H15 (CIRCA', '- **H15 (CIRCA, hồi quy làm tăng điểm).** Hai nhánh đổi cửa sổ cho trung vị tỷ số nhóm từ8 cha thấp hơn:7,54 xuống3,40 và3,64; vẫn có67–73% nút tăng điểm (KQ13 mục6). Cửa sổ có giá trị chẩn đoán vì thứ hạng cũng thay đổi, nhưng chưa xác định riêng nguyên nhân là số điểm học hay khoảng cách đến đoạn chấm: phân phối nền và tập nút đổi cùng. Cả hai mốc khai trước không đạt trọn. Cửa sổ đã khóa và số đã chấm giữ nguyên.'),
    153: ('MicroRank: không phải chờ', '- **MicroRank: chưa phân xử đầy đủ đường chờ → cờ → nhóm trace → điểm.** Các tiêu chí hiện có không hỗ trợ chờ ở đa số cặp: dịch vụ phía trên chỉ4/132 cặp RE2-TT (kỳ vọng ngẫu nhiên18,5), và từ nửa trace bất thường gắn root ở0/10,4/16 cặp. Quan sát nổi bật là thao tác có mặt trong nhiều trace bất thường không gắn root; ts-station-service đứng đầu21/24 ca sai (KQ11 mục1,2.2). Những số này không bác bỏ việc cờ do chờ góp phần giữ trace trong nhóm. Bổ sung theo trace được lưu riêng sau REVIEW; không lấy hạng gần như giữ nguyên để kết luận không có chờ.'),
    215: ('15/52', '5. 15/52 ca không đủ lời gọi tới root; trong8 ca không có cạnh gọi đi vào root. Các quan hệ đi ra, cha–con, máy–dịch vụ hoặc log/metric chưa được phép này đánh giá. Với return, root không đứng đầu dưới cách chấm hiện tại; đáp ứng do lỗi vẫn OPEN.'),
    220: ('Thêm ở phiên 13', '**Thêm ở phiên13, một thuận và một giới hạn.** Tỷ lệ cờ thao tác phía trên root tăng0,8% →6,2% giữa mốc giả/thật cùng độ dài cửa sổ, còn thao tác không liên hệ giữ1,1–1,2% (KQ13 mục2); với TraceRCA có chờ qua hai tầng gọi với cùng số span (doc-tay mục8.3 điểm8). Đây là căn cứ đề xuất thử gắn theo từng cạnh. Trong phần MicroRank còn sai,8–10/20–24 ca có thao tác đứng đầu gắn root theo tiêu chí bảng nối; các ca khác gồm không gắn, ít span và chưa rõ, không tự chứng minh mọi quan hệ đồ thị đều không giúp.'),
    227: ('Cách xếp hạng', '- Cách xếp hạng "kiểu MicroRank": ghép bộ chia và đếm riêng cho17–19/25 ca RE2-TT,6–8/22 ca Nezha-OB hạng1 (KQ12 mục1). Phần còn lại có ba dạng quan sát cùng ca chưa rõ và một ca không gắn nhưng vẫn có root trong trace xét (KQ13 mục5). Chưa đủ chọn hay loại thiết kế. Luật theo từng span xếp37% trace bất thường ở mốc giả (KQ13 mục1), là căn cứ thử tiêu chí cả yêu cầu, chưa xác nhận lợi ích trên test.'),
    234: ('Đã chạy', '- **Đã chạy ở phiên12–13:** KT-3 và bảng nối MicroRank; KT-15 về DA; KT-8 cả hai nửa; KT-1,KT-2 mốc giả; KT-12 chuỗi độ trễ; KT-9 cửa sổ; đọc tay nốt. Bảng nối có ba dạng quan sát và ca chưa rõ. Nezha-OB có phép thử giả giữa nền ở runs/root-signal-placebo-003/ (22/22 ca), nhưng nền ngắn và cửa sổ không tương đương mốc thật; không thay phép KT-1 lùi150 giây. BARO/SimpleRCA trong bảng placebo là số mốc thật được nối vào, không phải đo lại ở mốc giả. Đáp ứng return còn OPEN; phần tăng điểm CIRCA và một mẫu P99 cũng còn mở.'),
    262: ('ở 8 ca đồ thị', '| 15/52 ca không đủ lời gọi tới root | Dữ liệu | Kết luận về chờ trên37 ca; ở8 ca cách dựa riêng vào cạnh đi vào root không áp dụng. Chưa kết luận về mọi loại quan hệ đồ thị |'),
    266: ('ba dạng', '| MicroRank: phần cặp còn lại sau các phép đổi | Thuật toán | Còn25–26/47 ca sau thay bộ chia,20–24/47 sau ghép đếm riêng; có ba dạng quan sát, ca chưa rõ và ca không gắn nhưng root vẫn hiện diện (KQ13 mục5). Không ép thành ba nguyên nhân bao trùm |'),
    278: ('| 3.', '| 3. Chỉ nhận cơ chế khi có chuỗi đầu vào → xử lý → trung gian → đầu ra | Đạt một phần | Một số chuỗi tính toán đã xác nhận; đáp ứng return, đường cờ/nhóm của MicroRank, ca ghép chưa rõ và nguyên nhân độ nhạy cửa sổ chưa phân xử hết |'),
    281: ('| 6.', '| 6. Nhật ký và bàn giao | Đạt | LOG phiên12–13 và mục sửa sau REVIEW; bản sửa chờ kiểm lại độc lập |'),
}, {35: '**Lưu ý sau REVIEW.** Các bản theo phiên và khóa no_signal trong JSON cũ được giữ để bảo toàn lịch sử. Khóa ấy chỉ đếm root không hạng1 theo các cách chấm; không chứng minh không có đáp ứng do lỗi. Đọc kết luận hiện tại ở bản này và phần đính chính sau REVIEW của KQ13. Bằng chứng, bản trước và manifest mới ở runs/sua-review-001/.',
    238: '- **Bổ sung sau REVIEW được Minh duyệt:** thu cờ và nhóm trace của MicroRank M-D từ đầu vào dev cũ, không chạy lại PageRank; kiểm lại số đọc tay. Ca dev-14701a3bbb chưa phân xử vì sao thao tác đứng đầu được chấm cao; dev-607751ac0a dưới luật code không gắn theo cây con dù root có trong một phần trace xét. Nhãn dịch vụ gây lỗi đã biết; điều chưa rõ là bước nào làm xếp sai và cách sửa nào có căn cứ.'})

edit('ket-qua-phien-13.md', {
    151: ('mức mô tả', '**Đọc, ở mức mô tả.** Có ba dạng quan sát trong phần MicroRank còn sai sau ghép hai phép đổi; chúng không bao phủ mọi ca và chưa là ba nguyên nhân đã xác nhận:'),
    154: ('Nhóm trace bất thường mới không chứa root', '2. **Các trace tạo số đếm cho thao tác đứng đầu không chứa root:**3 ca RE2-TT và6 ca Nezha-OB theo luật bài,4 ca theo luật code. Đây là tập trace gắn với thao tác cao nhất có cờ, không phải toàn bộ nhóm trace bất thường. Một ca không gắn theo luật code vẫn có root trong trace xét; xem phần chưa rõ dưới đây.'),
    157: ('Giới hạn.', '**Phần chưa rõ và giới hạn.** dev-14701a3bbb (shippingservice,cpu_contention) là cùng một ca chưa rõ dưới cả hai luật: tỷ lệ gắn root2/5 và8/15, thấp hơn tỷ lệ gắn currencyservice4/5 và13/15. Với dev-607751ac0a (checkoutservice,network_delay), luật code cho0/6 span gắn root theo cây con nhưng2/6 trace vẫn chứa root, một trace có root mang cờ. Vì vậy không đồng nhất không gắn với root vắng mặt. Cả14 ca Nezha theo luật code gồm5 gắn,5 không gắn,1 chưa rõ,3 ít span; trong5 không gắn chỉ4 ca vắng root ở tập trace xét. Cần lần theo đồ thị, trọng số và số đếm của các ca chưa rõ để phân xử; không gọi là dạng cơ chế thứ tư đã xác nhận. Nhánh ghép là chẩn đoán, mốc50%/20% do người làm đặt; dự đoán viết sau kết quả kiểm tên thao tác. Nguồn: runs/microrank-merged-link-001/summary.json → /cases (case_id và từng nhánh); derived-013.json → /merged_link/by_dataset/Nezha-OB.'),
    187: ('giải thích khoảng', '- Theo mốc đã khai, cả hai nhánh không đạt trọn. Quan sát: trung vị tỷ số ở nút nhiều cha giảm từ7,54 xuống3,40 và3,64; hồi quy vẫn làm tăng điểm ở đa số nút. Không dùng điều này để bác bỏ mọi ảnh hưởng của cửa sổ hoặc tách riêng nguyên nhân: tập nút, phân phối nền và giai đoạn lỗi cùng đổi. Ở tf, tỷ số vẫn tăng từ1,03 tới3,40 theo số cha.'),
    195: ('ba phần tách được', '**Đọc, ở mức tính toán.** Hai phép đổi xác nhận điểm và thứ hạng nhạy với cửa sổ. Chúng chưa tách được ba nguyên nhân độc lập: học291 điểm đổi cả độ dài và dữ liệu nền; chấm ngay sau mốc đổi cả giai đoạn lỗi, có ca lỗi chưa hiện rõ; bước lọc cột làm tập nút khác nhau. Bởi vậy7,54 →3,40/3,64 là kết quả của hai cấu hình chẩn đoán, không phải tỷ lệ phần nguyên nhân do ít điểm học hay chấm xa. Phần dư còn cao và tăng theo số cha phù hợp với quan sát KQ10 mục1.4, nhưng chưa có phép đổi riêng phân xử phần còn lại.'),
    203: ('Không thấy đường thất bại mới', '- Phần đọc nốt thêm các điều chỉnh về thang BARO, độ dao động nền auth|delay, chờ qua hai tầng, T-D theo cạnh và TORAI nguồn log (doc-tay mục8). Với MicroRank, ba dạng chỉ là dạng quan sát; bảng nối còn ca chưa rõ và một ca không gắn nhưng root có trong trace. Không nhận là đã xác định hết đường thất bại.'),
    209: ('| "`frontend`', '| "frontend đứng đầu … khớp với H4,H7" | KQ12 mục1; KT-3; báo cáo mục5.1 | Chỉ3/14 và3/11 gắn theo bảng nối; các ca khác gồm không gắn, ít span và chưa rõ. Không gắn không luôn là root vắng mặt | Mục5 và đính chính sau REVIEW |'),
}, {217: '**Đính chính sau REVIEW, Minh duyệt11/10.** Không suy từ root không hạng1 sang không có tín hiệu do lỗi; không bác bỏ chờ trong MicroRank chỉ vì M-D gần giữ hạng; giữ ca chưa rõ và ca không gắn nhưng root hiện diện; không tách ba nguyên nhân của CIRCA từ hai phép đổi cửa sổ. Bản trước và bằng chứng sửa ở runs/sua-review-001/. Self-check E cũ kiểm mục1–6; mục7 và doc-tay mục8 được đối chiếu riêng trong kiem-so/ của lượt sửa này. Bản lịch sử ở mục9 mô tả chi phí và cách chạy của phiên13, không phải lượt sửa này.'})

edit('doc-tay.md', {
    70: ('Lỗi `return`', '4. **"Không xét được", tỷ lệ cứu — dev-3b92690644 (checkoutservice|return), hạng7** (3 đơn vị). Root4/132 (3%). Các thao tác trên root có1–4% cờ (currencyservice101/2.981,frontend133/4.254). a/n đưa root lênhạng1; chưa lưu thao tác thắng của root trong nhánh ấy. Tỷ lệ cờ native nhỏ không chứng minh thời lượng không phản ứng với lỗi hoặc thứ hạng chỉ do nhiễu nền.'),
    71: ('lỗi không để lại', '5. **Không chờ, tỷ lệ không cứu — dev-27252dca60 (productcatalogservice|exception), hạng8** (2 đơn vị). Root3/1.089 (0,3%); không đứng đầu ở vị trí trace nào. a/n hạng8, a/n từ20 span hạng5, a hạng4–5. Đây là quan sát về cờ và cách chấm; đáp ứng thời lượng do lỗi chưa phân xử, chưa quy riêng cho thiếu dữ liệu.'),
    73: ('toàn bộ tín hiệu', '7. **"Chờ root" một phần — dev-5467884de4 (recommendationservice|network_delay), hạng7** (4 đơn vị). Root7/450 (2%), span phía gọi của frontend439/450 (98%),99% là span chờ root. Năm thực thể khác2–9% cũng đứng trên root. a/n hạng9,T-D không đổi; bước theo bài đưa root hạng2. Cờ hiện rõ hơn ở phía gọi; không có nghĩa span của root không đổi. Gắn bằng chứng phía gọi về dịch vụ được gọi là ứng viên cần đánh giá, chưa chứng minh phải dùng cách ấy mới xếp đúng.'),
    80: ('lỗi `return` không để lại', '- **Đọc:** root có11 span mang cờ nhưng không hạng1. Chưa tách cờ do lỗi khỏi nhiễu nền; không kết luận return không làm đổi thời lượng. Ca này không có cạnh đi vào root, còn cạnh root gọi dịch vụ khác vẫn có.'),
    85: ('Không có tín hiệu', '- **dev-8ecd9880ed (checkoutservice|return), hạng[5,6] ở k=5.** Root2/28; không đứng đầu ở vị trí trace nào, hòa ở biênhạng5 giữa điểm nhỏ. Chưa có bằng chứng phân xử đáp ứng do lỗi và cờ nền; không suy từ hạng ra dữ liệu không có dấu hiệu.'),
    90: ('span của root không có gì', '- **Đọc:** ca này không thao tác nào của root mang cờ theo ngưỡng đang dùng; adapter loại root vì không có điểm hữu hạn. Span phía gọi mang bằng chứng chậm. Đây là chuỗi tính toán cụ thể của ca này, không suy rộng rằng span của root luôn không có tín hiệu ở mọi ca trễ mạng.'),
    94: ('lỗi không để lại tín hiệu', '- Có ba đường quan sát: gắn span phía gọi cho dịch vụ gọi; thao tác đông span thắng nhờ số tuyệt đối; root ít cờ và không được cách chấm hiện tại tách ra. Hai đường đầu có bằng chứng tính toán theo ca; đường cuối chưa xác nhận lỗi không làm đổi thời lượng. Một ca có thể có nhiều đường.'),
    96: ('chỉ thông tin trên cạnh', '- Với một phần ca trễ mạng ở Nezha-OB, các phép đổi đã thử chưa đưa root hạng1 và cờ phía gọi rõ hơn cờ root. Đây là căn cứ đề xuất dùng cạnh; không bác bỏ mọi phép chấm theo nút hoặc mọi tín hiệu của root.'),
    143: ('Lỗi `return` không để lại', '- **dev-1ac905bc95 (frontend|return), hạng3.** Root ở điểm vào; hai thực thể trên root là dịch vụ root gọi. A′ cho hạng[1,3]; luật bài lênhạng1, luật code giữhạng3. Kết quả không ổn định giữa luật; đáp ứng thời lượng do return còn OPEN (mục1.5).'),
    188: ('metric của chính root không đổi', '- **dev-5ada15752d (frontend|return), hạng8** (2 đơn vị) và **dev-1ac905bc95, hạng10/10** (3 đơn vị). Root z=3,9 và1,2; mọi thực thể trên root là dịch vụ root gọi, lưu lượng một số dịch vụ đó đổi. B-2 không đổi hạng. Quan sát là khác biệt giữa lưu lượng phía dưới và điểm metric của root; chưa quy thay đổi ấy cho lỗi return hoặc khẳng định metric root không đổi từ hạng thấp.'),
    229: ('không để lại tín hiệu metric', '- **dev-1ac905bc95 vàdev-5ada15752d (frontend|return), hạng[5,6] và6:** root0 phiếu metric ở0/21 cột,1 phiếu log; các thực thể trên root là dịch vụ root gọi. Không có phiếu theo ngưỡng này không đồng nghĩa metric không đổi do lỗi; đáp ứng return chưa phân xử.'),
    339: ('root không có tín hiệu', '6. **Ở return tại điểm vào, lưu lượng dịch vụ phía dưới có đổi trong khi root có điểm thấp hoặc không có phiếu metric** (mục3.3,4.2). Quan sát hướng phía dưới khác giả thuyết chờ ở phía trên; chưa xác nhận thay đổi do return hay thiếu tín hiệu trong dữ liệu.'),
    359: ('không để lại tín hiệu metric', '1. **dev-8ecd9880ed (Nezha-OB,checkoutservice|return), hạng8/10.** Cột tốt nhất root: độ trễ phía gọiP95,z=4,2,IQR/median34%,lệch/median143%. adservice z=523,3 (398%,0,76%); paymentservice z=144 (2%,0,013%). B-2 hạng7;6/7 thực thể trên root không phía trên. Root có thay đổi và có điểm; chưa phân xử phần do lỗi với nền, không thể gọi dữ liệu không có tín hiệu chỉ vì root không hạng1.'),
    363: ('lỗi ở dịch vụ phía trên', '5. **dev-3b92690644 (Nezha-OB,checkoutservice|return), hạng3.** Root độ trễ phía gọiP99,z=40,lệch/median211%. shippingservice mạng nhậnz=216,lệch/median1.850%;adservice độ trễ phía serverP95,z=58,2. B-2 hạng4. Root có cột đổi cùng lúc phía dưới có cột đổi; chưa quy riêng cho lỗi hay xác nhận hướng lan.'),
    386: ('không để lại tín hiệu thời lượng', '5. **dev-5ada15752d (Nezha-OB,frontend|return), hạng3.** Root35/2.201 (2%);currencyservice94/2.447 (4%),checkoutservice8/46 (17%). T-D vàa/n làm root xuốnghạng6. Như mục1.5, có cờ nhưng root không hạng1; đáp ứng do lỗi chưa phân xử.'),
    393: ('không có tín hiệu thời lượng', '**Phần đọc nốt thêm cho TraceRCA.** Trong10 đơn vị, quan sát span phía gọi ở1,2,7,8,9,10; khối lượng ở3,4,6,9; root ít cờ/không hạng1 ở5, chưa xác nhận thiếu đáp ứng do lỗi. Trong9 đơn vị Nezha, frontend đứng đầu6 (1,2,3,7,8,9),currencyservice ở4,5,recommendationservice ở6. Hai điều mới: chờ qua hai tầng với cùng số span (8), T-D khác nhau ở hai ca RE2-TT cùng dạng (10).'),
    412: ('span của root không mang cờ', '7. dev-5467884de4 (recommendationservice|network_delay), hạng5: A=484 (77%);root tự mang cờ ở7 trace. Chia theo bài đưa root hạng1; ghép làm root hạng4/5,frontend đứng đầu.97–98% span mang cờ thao tác phía gọi có con trực tiếp root và bao lời gọi chậm;root mang cờ6–7/67–199 trace ấy. Đếm riêng lấy điểm từ ít cờ root so với phía gọi, không phải root hoàn toàn không mang cờ. Đây là cơ chế tính toán gắn span cho dịch vụ sở hữu nó của ca này.'),
    452: ('ba dạng đọc được', '- Ba dạng quan sát sau ghép là span phía gọi được tính cho dịch vụ gọi; các trace tạo số đếm của thao tác đứng đầu vắng root; hoặc ít span. Chưa bao phủ mọi ca: dev-14701a3bbb chưa rõ dưới cả hai luật; dev-607751ac0a luật code không gắn theo cây con nhưngroot cótrong2/6 trace xét. Nhãn root đã biết; chưa rõ cơ chế xếp sai và cách sửa có căn cứ. Nguồn cụ thể: KQ13 mục5 và runs/microrank-merged-link-001/summary.json → /cases.'),
    455: ('Không có phản ví dụ', '-28 đơn vị đọc nốt không chứng nhận ba dạng đã giải thích mọi ca. Bảng nối giữ nguyên ca chưa rõ và ca không gắn nhưngroot hiện diện; bốn đơn vị nhómA được mô tả theo tập trace tạo số đếm của thao tác đứng đầu. M-D có một ca đưa root hạng1 (đơn vị5), giữ nguyên phản ví dụ ấy.'),
}, {12: '**Đính chính sau REVIEW (Minh duyệt11/10).** Cờ, phiếu và hạng là đầu ra của cách chấm; chúng không tự xác nhận có/không có đáp ứng do lỗi. Bảng no_signal cũ thực chất đếm không hạng1. Nezha-OB có mốc giả giữa nền (22/22 ca), nhưng cửa sổ ngắn/không tương đương; BARO/SimpleRCA trong bảng đó được nối từ mốc thật. Không dùng chúng làm đối chứng metric/log ở mốc giả. Đọc tay MicroRank gồm48 đơn vị:46 OK sai,1 ERROR,1 đối chứng đúng; ngoài phần đọc có3 ERROR và1 OK đúng. Bằng chứng kiểm số của mục8 lưu ở runs/sua-review-001/kiem-so/.'})

edit('kiem-tiep.md', {
    19: ('ba dạng', '| KT-3 | 25–26/47 ca MicroRank chưa hạng1 sau thay bộ chia | Đã chạy phiên12–13; ba dạng quan sát, còn ca chưa rõ và ca không gắn nhưng có root | — | Có lấy kiểu xếp hạng MicroRank làm ứng viên |'),
    25: ('giải thích khoảng', '| KT-9 | CIRCA nhạy với cửa sổ hay số cha | Đã chạy phiên13; trung vị tỷ số thấp hơn trong hai nhánh, chưa tách riêng nguyên nhân | — | Có dùng hồi quy theo cấu trúc ởP6 |'),
    80: ('ba dạng', '- **Bảng nối phiên13** (KQ13 mục5;runs/microrank-merged-link-001/summary.json). Hai tập trace khớp47/47 ca theo hai luật. frontend đứng đầu14/16 và11/14 ca Nezha còn sai, gắnroot ở3/14 và3/11; dự đoán H4,H7 không đạt. Có5/8,3/6 ca RE2 và5/16,5/14 ca Nezha gắnroot;3 ca RE2,6/4 ca Nezha vắngroot trong tập trace tạo số đếm của thao tác đứng đầu;4/3 ca Nezha ítspan. dev-14701a3bbb chưa rõ dưới cả hai luật. dev-607751ac0a luậtcode không gắn nhưngroot cótrong2/6 trace xét. Các dạng này chưa là phân loại nguyên nhân đầy đủ; giữ giải thích(b),(c) chưa kiểm riêng.'),
    103: ('không để lại tín hiệu thời lượng', '- **Điều kiện thất bại biết trước.**15/52 ca thiếu lời gọi tới root,8 ca không có cạnh đi vào; không đồng nghĩa mọi quan hệ đồ thị đều vô ích. Return/exception córoot không hạng1 và ítcờ ở một số ca; đáp ứng thời lượng do lỗi còn OPEN. Lời gọi song song hoặc bất đồng bộ có thể khác điều kiện dev (chưa thấy ở dev, có thể có ở FlashTicket).'),
    142: ('giải thích khoảng', '- Hai vế mốc khai trước cần cùng đạt; vế tỷ số đạt, vế tỷ lệ nút tăng không đạt ở cả hai nhánh. Cả(a),(b) không đạt trọn. Hai nhánh cho trung vị nhóm nhiều cha thấp hơn, còn đa số nút tăng điểm; chưa tách riêng ảnh hưởng số điểm học, phân phối, thời điểm chấm và tập nút.'),
}, {32: '\n## Bổ sung sau REVIEW được Minh duyệt11/10\n\n- **Return và vị trí tín hiệu: OPEN.** Root không hạng1 khác với dữ liệu không có đáp ứng. Đã có mốc giả giữa nền Nezha ở runs/root-signal-placebo-003/; nền ngắn, cửa sổ/baseline khác mốc thật và BARO/SimpleRCA được nối từ số thật. Cần đối chứng đáp ứng cùng đại lượng và cửa sổ đủ tương đương để tách lỗi khỏi nền; hiện chưa đủ kết luận không có tín hiệu. Ảnh hưởng: không quy H8 hoàn toàn cho dataset, không loại thiết kế quan sát chỉ từ hạng. FlashTicket cần log mã lỗi và nền phù hợp; collector không khôi phục dữ liệu chưa ghi.\n- **MicroRank M-D, cờ → nhóm → điểm: đang kiểm bổ sung** tại runs/sua-review-001/md-partition/. Dựng lại cờ duration/uncovered và OR theo trace từ đầu vào cũ; lưu dịch vụ giữ nhóm, trace đổiA/N và coverage/count theo thao tác; không chạy lại PageRank. Nhãn chỉ nối sau để diễn giải. Chi phí đề xuất20–30phút là ước lượng; thời gian thực ghi trong kết quả mới. Khi nhóm bất thường/bình thường và đồ thị đầu vào không đổi, xóa cờ riêng caller không làm đổi đếmphủ; khi nhóm đổi, chưa suy được hạng nếu chưa lần theo trọng số/điểm. Ảnh hưởng: chỉ kết luận về bước chia/đếm đã kiểm, không bác bỏ chờ từ M-D giữhạng.\n- **Ca ghép chưa rõ: OPEN.** dev-14701a3bbb dưới cả hai luật,dev-607751ac0a luậtcode córoot nhưngkhông gắn theo câycon. Thiếu chuỗi đồ thị → trọng số → sốđếm → điểm theo thao tác cho đúng các ca này và đối chứng tương ứng; đọc trung gian cũ trước khi đề xuất lượt mới. Chưa có chi phí đáng tin cho phần thu thêm (nếu thiếu), không tự chạy ngoài quyền. Ảnh hưởng: chưa chọn thành phần để chữa phần còn lại chỉ từba dạng quan sát.\n- **CIRCA: OPEN về nguyên nhân độ nhạy cửa sổ.** Giữ số và hai mốc không đạt trọn. Muốn tách nguyên nhân cần giữ tập nút và tách thay đổi độ dài khỏi phân phối/giai đoạn lỗi; chưa có thiết kế hay chi phí cho phép mới, không dùng như căn cứ đã xác nhận.'})
